export const FACT_OPINION_CLAIM_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu fakta",q:"Sebuah 'fakta' adalah pernyataan yang...",options:["bisa diperiksa benar atau salahnya dengan bukti","dianggap benar kalau banyak orang menyetujuinya","menyatakan perasaan seseorang tentang sesuatu"],answer:0,explain:"Fakta adalah klaim yang bisa dicek. Ia bisa terbukti benar atau ternyata salah — yang penting ia bisa diuji.",hint:"Bisa dicek benar/salahnya."},
{n:2,type:"mcq",micro:"Apa itu opini",q:"Sebuah 'opini' adalah pernyataan yang...",options:["dapat dibuktikan benar atau salah dengan satu alat ukur yang sama untuk semua pengukur","mengungkapkan perasaan, selera, atau penilaian seseorang & bisa berbeda antar orang","ditentukan oleh jumlah orang yang setuju, lalu hasilnya sama di mana pun"],answer:1,explain:"Opini mencerminkan sudut pandang. Orang yang berbeda bisa punya opini berbeda tentang hal yang sama.",hint:"Perasaan atau penilaian, bukan ukuran."},
{n:3,type:"mcq",micro:"Membedakan",q:"Mana yang merupakan FAKTA?",options:["Bakso lebih enak daripada soto","Bakso adalah makanan paling enak","Bakso biasanya berbentuk bulat"],answer:2,explain:"'Berbentuk bulat' bisa diperiksa. 'Paling enak' & 'harus suka' adalah opini.",hint:"Mana yang bisa kamu buktikan dengan melihat?"},
{n:4,type:"mcq",micro:"Membedakan",q:"Mana yang merupakan OPINI?",options:["Warna biru lebih indah daripada warna hijau","Indonesia memiliki ribuan pulau","Air mendidih pada suhu sekitar 100 derajat Celsius di dataran rendah"],answer:0,explain:"'Lebih indah' adalah penilaian selera. Dua pernyataan lain bisa diperiksa.",hint:"Mana yang tergantung selera?"},
{n:5,type:"tf",micro:"Fakta bisa salah",q:"Benar atau Salah: Sebuah pernyataan tetap tergolong 'pernyataan fakta' meski setelah dicek ternyata keliru, asalkan ia memang bisa dicek.",answer:true,explain:"'Bumi berbentuk kubus' adalah pernyataan fakta yang salah — tetap fakta karena bisa diuji. Kunci pembeda fakta adalah 'bisa dicek', bukan 'pasti benar'.",hint:"Bisa dicek, walau hasilnya salah."},
{n:6,type:"mcq",micro:"Kata penanda opini",q:"Kata-kata yang sering menandai OPINI:",options:["'jumlahnya', 'panjangnya', 'suhunya'","'menurutku', 'terbaik', 'seharusnya', 'membosankan'","'berukuran', 'terjadi pada tahun', 'terdiri dari', 'berjumlah'"],answer:1,explain:"Kata penilaian & perasaan (terbaik, seharusnya, membosankan) menandai opini. Kata ukuran & peristiwa menandai fakta.",hint:"Kata perasaan & penilaian."},
{n:7,type:"mcq",micro:"Apa itu klaim",q:"Sebuah 'klaim' adalah...",options:["kebohongan yang sengaja disampaikan untuk menipu orang lain dan membuat mereka percaya begitu saja","fakta yang sudah terbukti benar oleh banyak penelitian dan tak perlu diperiksa lagi oleh pembacanya","pernyataan yang seseorang sampaikan sebagai benar, yang masih perlu diperiksa buktinya"],answer:2,explain:"Klaim adalah pernyataan yang diajukan sebagai benar. Klaim yang baik didukung bukti; klaim yang buruk tidak.",hint:"Diajukan sebagai benar, tapi perlu dicek."},
{n:8,type:"tf",micro:"Opini tidak 'salah'",q:"Benar atau Salah: Karena opini adalah penilaian pribadi, semua opini sama kuatnya & tidak ada yang lebih beralasan.",answer:false,explain:"Opini tidak 'salah' seperti fakta, tetapi opini yang didukung alasan & bukti jauh lebih kuat daripada opini tanpa dasar.",hint:"Ada opini berdasar & opini kosong."},
{n:9,type:"mcq",micro:"Bukti",q:"'Bukti' untuk sebuah klaim adalah...",options:["informasi (data, pengamatan, catatan) yang mendukung atau melawan klaim","perasaan yakin yang dimiliki penyampai klaim saat mengucapkannya","pengulangan klaim itu dengan suara lebih keras"],answer:0,explain:"Bukti adalah bahan yang bisa diperiksa orang lain, bukan sekadar keyakinan atau pengulangan.",hint:"Sesuatu yang bisa ditunjukkan & diperiksa."},
{n:10,type:"mcq",micro:"Fakta sehari-hari",q:"Mana pernyataan FAKTA?",options:["Film itu terlalu panjang","Film itu berdurasi 2 jam 15 menit","Film itu seharusnya tidak pernah dibuat"],answer:1,explain:"Durasi bisa diperiksa. 'Terlalu panjang' & 'seharusnya tidak dibuat' adalah opini.",hint:"Mana yang bisa diukur dengan jam?"},
{n:11,type:"open",micro:"Fakta & opini tentang sekolahmu",q:"Tuliskan satu pernyataan FAKTA & satu pernyataan OPINI tentang sekolahmu, lalu jelaskan bagaimana kamu tahu yang mana yang mana.",explain:"Fakta bisa diperiksa dengan cara yang sama oleh siapa pun; opini bergantung pada sudut pandang.",hint:"1 fakta + 1 opini + cara membedakannya.",sample:"Fakta: 'Sekolahku memiliki 18 ruang kelas.' Aku tahu ini fakta karena bisa dihitung & dicek langsung. Opini: 'Kantin sekolahku adalah tempat paling menyenangkan.' Ini opini karena 'paling menyenangkan' bergantung pada selera; teman lain mungkin lebih suka perpustakaan."},
{n:12,type:"mcq",micro:"Pernyataan campuran",q:"'Gedung itu setinggi 40 meter & terlihat menakutkan.' Kalimat ini...",options:["seluruhnya fakta, dan semua bagiannya bisa diukur dengan alat","seluruhnya opini, dan ditulis berdasarkan perasaan penulisnya","campuran: 'setinggi 40 meter' fakta, 'terlihat menakutkan' opini"],answer:2,explain:"Satu kalimat bisa memuat fakta & opini sekaligus. Pisahkan keduanya saat menilainya.",hint:"Pecah kalimat menjadi dua bagian."},
{n:13,type:"tf",micro:"Memeriksa fakta",q:"Benar atau Salah: Cara memeriksa sebuah klaim fakta cukup dengan menanyakan apakah kita menyukainya atau tidak.",answer:false,explain:"Sebaliknya, klaim fakta diuji dengan bukti yang bisa diperiksa — sumber tepercaya, catatan resmi, pengukuran, atau percobaan — bukan dengan suka atau tidak suka.",hint:"Bukti, bukan selera."},
{n:14,type:"mcq",micro:"Opini terselubung",q:"'Semua orang tahu bahwa liburan ke gunung lebih seru daripada ke pantai.' Pernyataan ini sebenarnya...",options:["opini tentang selera liburan yang dibungkus seolah-olah fakta","fakta ilmiah tentang kenyamanan liburan yang sudah dibuktikan banyak penelitian","prediksi tentang cuaca di gunung & pantai yang bisa dicek besok pagi"],answer:0,explain:"Frasa 'semua orang tahu' sering dipakai untuk menyamarkan opini agar terdengar seperti kebenaran yang tak terbantah.",hint:"'Lebih seru' itu selera siapa?"},
{n:15,type:"open",micro:"Ubah opini jadi argumen",q:"Ambil opini 'Perpustakaan sekolah sebaiknya buka saat istirahat'. Tuliskan opini itu lalu tambahkan satu alasan & satu bukti yang mendukungnya.",explain:"Opini menjadi argumen ketika disertai alasan (mengapa) & bukti (data atau fakta pendukung).",hint:"Opini + alasan + bukti.",sample:"Opini: Perpustakaan sekolah sebaiknya buka saat istirahat. Alasan: banyak murid ingin membaca atau mengerjakan tugas di waktu luang itu. Bukti: dari tanya-tanya ke satu kelas, 20 dari 30 murid mengatakan akan memakai perpustakaan saat istirahat jika dibuka."},
{n:16,type:"mcq",micro:"Fakta vs tebakan",q:"'Besok jumlah pengunjung perpustakaan akan 50 orang.' Sebelum besok tiba, pernyataan ini adalah...",options:["fakta yang sudah benar, dan kata 'akan' menandakan kepastian","prediksi/klaim tentang masa depan yang belum bisa diperiksa sekarang","opini pribadi yang tak bisa dibuktikan benar atau salah oleh orang lain"],answer:1,explain:"Pernyataan tentang masa depan belum bisa dicek sampai waktunya tiba; ia klaim/prediksi, bukan fakta yang sudah terbukti.",hint:"Belum terjadi = belum bisa dicek."},
{n:17,type:"order",micro:"Menilai sebuah klaim",q:"Urutkan langkah menilai apakah sebuah klaim layak dipercaya:",items:["Tentukan apakah ini klaim fakta (bisa dicek) atau opini (selera/penilaian)","Jika klaim fakta, cari bukti pendukung & sumbernya","Nilai apakah bukti itu cukup, relevan, & dari sumber tepercaya","Simpulkan: dipercaya, ditolak, atau ditahan sampai bukti cukup"],answer:[0,1,2,3],explain:"Kenali jenis pernyataan → cari bukti → nilai bukti → simpulkan.",hint:"Kenali jenisnya dulu."},
{n:18,type:"mcq",micro:"Opini ahli",q:"Opini seorang dokter tentang cara merawat luka biasanya lebih kuat daripada opini orang biasa karena...",options:["dokter berbicara lebih yakin & lebih keras daripada orang lain","dokter memakai seragam putih & berbicara tenang, lalu ucapannya lebih dipercaya orang","opini itu didasari pengetahuan & pengalaman terlatih di bidang tersebut"],answer:2,explain:"Opini yang berdasar keahlian & bukti (informed opinion) lebih kuat daripada sekadar selera — walau tetap bukan kepastian mutlak.",hint:"Berdasar keahlian & bukti, bukan sekadar percaya diri."},
{n:19,type:"tf",micro:"Fakta netral",q:"Benar atau Salah: Pernyataan 'suhu hari ini 34 derajat' berhenti menjadi pernyataan fakta jika banyak orang mengeluh cuacanya tidak nyaman.",answer:false,explain:"Sebaliknya, fakta tidak berubah karena perasaan orang. Yang berbeda-beda hanyalah opini apakah 34 derajat itu 'panas menyiksa' atau 'hangat nyaman'.",hint:"Angka tetap; perasaan tentang angka berbeda-beda."},
{n:20,type:"mcq",micro:"Ringkasan Fondasi",q:"Pembeda utama fakta, opini, & klaim:",options:["fakta bisa diperiksa; opini adalah penilaian/selera; klaim adalah pernyataan yang diajukan benar & masih perlu diperiksa buktinya","ketiganya sama saja, semuanya hanyalah kalimat yang diucapkan seseorang dengan yakin dan tidak bisa dibedakan dari isinya","fakta berupa angka, opini berupa kata sifat, & klaim hanyalah kalimat panjang yang diucapkan oleh pejabat penting"],answer:0,explain:"Menyortir pernyataan ke dalam ketiga jenis ini adalah langkah pertama berpikir kritis terhadap informasi.",hint:"Bisa dicek / penilaian / diajukan & perlu dicek."},
{n:21,type:"classify",micro:"Fakta atau opini",q:"Kelompokkan setiap pernyataan:",items:["Jerapah adalah hewan berleher panjang","Jerapah adalah hewan paling anggun di kebun binatang","Air laut terasa asin","Pelajaran olahraga seharusnya ditambah jamnya"],groups:["Pernyataan fakta","Pernyataan opini"],answer:{"Pernyataan fakta":["Jerapah adalah hewan berleher panjang","Air laut terasa asin"],"Pernyataan opini":["Jerapah adalah hewan paling anggun di kebun binatang","Pelajaran olahraga seharusnya ditambah jamnya"]},explain:"'Paling anggun' & 'seharusnya' menandai penilaian; leher panjang & rasa asin bisa diperiksa siapa saja.",hint:"Cari kata penilaian & kata 'seharusnya'."},
{n:22,type:"mcq",micro:"Mengenali fakta",q:"Mana yang murni pernyataan fakta?",options:["'Novel ini membosankan di bagian tengah.'","'Novel ini terdiri dari 24 bab.'","'Novel ini seharusnya lebih pendek.'"],answer:1,explain:"Jumlah bab bisa dihitung. Dua lainnya adalah penilaian.",hint:"Mana yang bisa dihitung?"},
{n:23,type:"mcq",micro:"Mengenali opini",q:"Mana yang merupakan opini?",options:["Kota itu berada di tepi sungai besar","Kota itu berpenduduk sekitar dua juta jiwa","Kota itu adalah tempat terbaik untuk tinggal"],answer:2,explain:"'Terbaik untuk tinggal' bergantung pada apa yang seseorang hargai; itu penilaian, bukan fakta.",hint:"Mana yang bisa diperdebatkan berdasarkan selera?"},
{n:24,type:"mcq",micro:"Klaim menyamar sebagai fakta",q:"'Produk ini terbukti membuat rambut tiga kali lebih kuat.' Sikap kritis:",options:["tanyakan: terbukti oleh siapa, dengan pengujian apa, & dibandingkan dengan apa","percaya begitu saja, dan kata 'terbukti' sudah berarti ada bukti yang kuat di baliknya","abaikan klaim iklan karena klaim produk itu bohong & tak perlu dipikirkan lagi"],answer:0,explain:"Kata 'terbukti' & angka membuat klaim terdengar faktual. Klaim tetap perlu bukti nyata: siapa yang menguji, caranya, & pembandingnya.",hint:"'Terbukti' oleh siapa & bagaimana?"},
{n:25,type:"tf",micro:"Sumber penting",q:"Benar atau Salah: Selama sebuah angka terdengar meyakinkan, kita tidak perlu tahu dari mana asalnya.",answer:false,explain:"Sebaliknya, bukti hanya sekuat sumbernya. Angka tanpa sumber yang jelas — sekeren apa pun terdengarnya — sulit dipercaya.",hint:"Dari mana datanya?"},
{n:26,type:"mcq",micro:"Bukti relevan",q:"Klaim: 'Sarapan membantu murid lebih fokus di kelas.' Bukti paling RELEVAN:",options:["testimoni satu murid yang merasa lebih fokus setelah sarapan di rumahnya","penelitian yang membandingkan fokus murid yang sarapan & yang tidak","jumlah murid yang membeli sarapan di kantin sekolah setiap harinya"],answer:1,explain:"Bukti relevan menguji klaim itu secara langsung — di sini, perbandingan fokus dengan & tanpa sarapan.",hint:"Bukti mana yang benar-benar menguji klaimnya?"},
{n:27,type:"mcq",micro:"Opini yang didukung baik",q:"Dua orang berbeda opini soal film. Opini siapa yang lebih kuat?",options:["yang berkata 'jelek banget, pokoknya membosankan & aku tak suka filmnya karena menurutku begitu'","yang berkata 'bagus sekali, orang lain juga akan suka & tak bisa menyangkalnya karena aku sudah menontonnya dua kali bersama teman'","yang berkata 'kurang bagus, karena alur di paruh kedua melompat-lompat & tiga tokoh penting tidak dijelaskan'"],answer:2,explain:"Opini yang menyebut alasan spesifik & bisa ditunjuk lebih kuat daripada opini tanpa alasan atau yang hanya lebih nyaring.",hint:"Mana yang memberi alasan yang bisa diperiksa?"},
{n:28,type:"open",micro:"Pisahkan dalam paragraf",q:"Baca: 'Taman kota dibuka tahun 2019. Luasnya sekitar 3 hektar. Sayangnya taman itu kurang terawat & pemerintah malas mengurusnya.' Tuliskan bagian mana yang fakta & bagian mana yang opini.",explain:"Dalam teks nyata, fakta & opini sering berdampingan. Memisahkannya membuat kita tahu bagian mana yang perlu bukti.",hint:"Tandai tiap kalimat: F atau O.",sample:"Fakta: taman dibuka tahun 2019; luasnya sekitar 3 hektar (keduanya bisa dicek). Opini: 'kurang terawat' adalah penilaian (walau bisa didukung bukti seperti foto rumput tinggi), & 'pemerintah malas mengurusnya' adalah opini yang menuduh niat & butuh bukti kuat."},
{n:29,type:"mcq",micro:"Fakta dipakai menyesatkan",q:"'90% orang yang minum air putih pernah sakit flu, jadi air putih menyebabkan flu.' Masalahnya:",options:["faktanya mungkin benar, tapi dipakai untuk menarik kesimpulan sebab-akibat yang tidak masuk akal","air putih memang menjadi penyebab flu karena angkanya sudah sangat besar sekali","angkanya salah karena persentase sembilan puluh itu terlalu besar untuk dipercaya"],answer:0,explain:"Fakta yang benar bisa disusun untuk menyesatkan. Hampir semua orang minum air putih, jadi angka itu tidak membuktikan apa-apa tentang penyebab flu.",hint:"Fakta benar, kesimpulan ngawur."},
{n:30,type:"order",micro:"Dari pernyataan ke penilaian",q:"Urutkan langkah menanggapi pernyataan 'Kelas kita paling berisik di sekolah':",items:["Kenali ini klaim yang bisa dicek, bukan sekadar opini","Tentukan cara mengukurnya (mis. catatan teguran guru, pengukuran kebisingan)","Kumpulkan data & bandingkan dengan kelas lain","Simpulkan berdasarkan data, bukan berdasarkan kesan"],answer:[0,1,2,3],explain:"Ubah klaim samar menjadi sesuatu yang bisa diukur, kumpulkan data, lalu simpulkan.",hint:"Kenali jenis klaim dulu."},
{n:31,type:"mcq",micro:"Kata bermuatan",q:"'Rencana itu adalah pemborosan uang yang gila-gilaan.' Kata 'gila-gilaan' berfungsi...",options:["memberikan angka tepat tentang jumlah uang yang dihamburkan dalam rencana itu","menambahkan muatan emosi untuk mendorong opini pembaca, bukan menambah fakta","membuktikan bahwa rencana tersebut benar-benar menghabiskan uang dengan sia-sia"],answer:1,explain:"Kata bermuatan emosi (gila-gilaan, luar biasa, mengerikan) menggeser opini pembaca tanpa menambah bukti.",hint:"Menambah emosi, bukan menambah data."},
{n:32,type:"tf",micro:"Opini dalam berita",q:"Benar atau Salah: Judul berita bisa memuat opini atau pilihan kata yang menggiring, bukan hanya fakta.",answer:true,explain:"Judul dibuat untuk menarik perhatian. Membaca isi & memeriksa sumber lebih penting daripada mempercayai judul mentah-mentah.",hint:"Judul dibuat untuk menarik klik."},
{n:33,type:"mcq",micro:"Penilaian beralasan",q:"'Berdasarkan tiga sumber & data lima tahun, sungai ini lebih tercemar dari sebelumnya.' Pernyataan ini paling tepat disebut...",options:["opini murni yang tak membutuhkan bukti lagi","tebakan tanpa dasar, dan sungai tak bisa diukur","penilaian yang beralasan & didukung bukti"],answer:2,explain:"Ini bukan selera & bukan satu fakta sederhana — ini kesimpulan/penilaian yang dibangun dari kumpulan bukti.",hint:"Di antara opini murni & fakta tunggal."},
{n:34,type:"mcq",micro:"Cek silang",q:"Kamu menemukan klaim angka yang mengejutkan di satu situs. Langkah kritis berikutnya:",options:["cari apakah sumber lain yang tepercaya melaporkan angka yang sama & dari mana angka aslinya","langsung percaya & membagikannya kepada teman tanpa memeriksa asal angkanya","anggap salah tanpa memeriksa karena angka yang mengejutkan biasanya dibuat-buat"],answer:0,explain:"Cek silang antar sumber tepercaya membantu memisahkan fakta dari klaim yang salah atau dilebih-lebihkan.",hint:"Apakah sumber lain sepakat?"},
{n:35,type:"mcq",micro:"Bukti cukup?",q:"Klaim: 'Minuman ini bikin pintar.' Bukti yang diberikan: satu orang bercerita nilainya naik setelah meminumnya. Penilaianmu:",options:["klaim itu terbukti benar, ada orang yang mengalami sendiri hasilnya setelah meminum minuman tersebut","satu cerita pribadi bukan bukti yang cukup untuk klaim sebesar itu; butuh pengujian yang lebih luas & terkontrol","klaim itu salah karena satu orang saja tidak mungkin berkata jujur tentang nilainya yang naik"],answer:1,explain:"Satu kesaksian (anekdot) mudah dipengaruhi banyak hal lain. Klaim besar butuh bukti yang lebih kuat & bisa diulang.",hint:"Satu cerita ≠ pembuktian."},
{n:36,type:"open",micro:"Rancang cara cek",q:"Temanmu berkata 'Kantin kehabisan roti setiap hari sebelum jam 9'. Tuliskan cara sederhana untuk memeriksa apakah klaim ini benar.",explain:"Klaim fakta diuji dengan pengamatan yang sistematis, bukan dengan satu kali kebetulan.",hint:"Apa yang dicatat, berapa lama, tanya siapa.",sample:"Selama satu minggu, aku akan mencatat setiap hari: pukul berapa roti di kantin habis, atau apakah masih ada sampai istirahat. Aku juga bisa bertanya ke penjaga kantin berapa roti yang disiapkan & biasanya habis jam berapa. Setelah lima hari, aku bisa melihat apakah 'habis sebelum jam 9' benar setiap hari, kadang-kadang, atau tidak."},
{n:37,type:"mcq",micro:"Opini sebagai opini",q:"Cara paling jujur menyampaikan opini:",options:["'Film ini objektif jelek & yang suka itu keliru'","'Seluruh penonton setuju bahwa film ini jelek'","'Menurut saya film ini kurang seru karena...' "],answer:2,explain:"Menandai opini sebagai opini ('menurut saya') & memberi alasan lebih jujur daripada memaksakannya sebagai fakta atau kesepakatan semua orang.",hint:"Akui bahwa itu pandanganmu, beri alasan."},
{n:38,type:"tf",micro:"Diam bukan bukti",q:"Benar atau Salah: Jika tidak ada yang membantah sebuah klaim, itu membuktikan klaim tersebut benar.",answer:false,explain:"Sebaliknya, tidak adanya bantahan bisa berarti banyak hal (belum ada yang memeriksa, tidak berani, tidak peduli). Kebenaran klaim diuji oleh bukti, bukan oleh keheningan.",hint:"Tidak dibantah ≠ terbukti."},
{n:39,type:"mcq",micro:"Sumber tepercaya",q:"Untuk klaim fakta tentang kesehatan, sumber yang umumnya lebih tepercaya:",options:["lembaga kesehatan resmi, tenaga medis, atau jurnal ilmiah","akun media sosial dengan pengikut terbanyak & saran sehat","pesan berantai yang dibagikan banyak orang dari 'dokter terkenal'"],answer:0,explain:"Sumber tepercaya punya keahlian, tanggung jawab, & proses pemeriksaan. Itu tidak menjamin sempurna, tapi jauh lebih kuat daripada sumber anonim.",hint:"Siapa yang punya keahlian & tanggung jawab?"},
{n:40,type:"mcq",micro:"Ringkasan Pemahaman",q:"Saat menemui informasi baru, urutan pertanyaan yang berguna:",options:["'Siapa yang paling terkenal membicarakannya?' lalu 'Berapa banyak orang yang membagikannya?'","'Apakah ini fakta yang bisa dicek, opini, atau klaim?' lalu 'Apa buktinya & dari mana?'","'Apakah ini cocok dengan yang kupikirkan?' lalu 'Apakah banyak yang setuju?'"],answer:1,explain:"Menyortir jenis pernyataan & menuntut bukti adalah inti menilai informasi.",hint:"Jenis pernyataan → bukti & sumber."},
{n:41,type:"mcq",micro:"Terapan: iklan",q:"Iklan krim: 'Krim terbaik untuk kulit sehat!' Bagian mana yang klaim yang bisa diperiksa?",options:["'terbaik untuk kulit sehat' adalah fakta yang sudah dibuktikan lewat pengujian di laboratorium produsen","'kulit sehat' adalah klaim yang bisa diperiksa dengan melihat kulit satu orang yang memakainya selama seminggu penuh","tidak ada; 'terbaik' & 'kulit sehat' terlalu kabur untuk diperiksa tanpa definisi & pengujian yang jelas"],answer:2,explain:"Iklan sering memakai kata superlatif kabur ('terbaik') yang sulit diuji. Klaim yang jelas menyebut apa, dibanding apa, & diukur bagaimana.",hint:"Apa arti 'terbaik' & bagaimana mengukurnya?"},
{n:42,type:"mcq",micro:"Terapan: ulasan produk",q:"Ulasan online: 'Tas ini jahitannya lepas setelah dua minggu.' Ini...",options:["klaim fakta tentang ketahanan yang bisa dicek lewat ulasan lain & pengujian","opini murni, pengalaman satu orang tak mungkin dicek oleh pembeli lain","prediksi tentang masa depan tas itu yang belum bisa dibuktikan sekarang"],answer:0,explain:"Pengalaman spesifik & bisa diperiksa ('jahitan lepas setelah dua minggu') adalah klaim fakta, berbeda dari opini selera. Cek apakah banyak ulasan lain menyebut hal sama.",hint:"Bisa dicek dengan ulasan lain?"},
{n:43,type:"mcq",micro:"Terapan: judul berita",q:"Judul: 'Warga Geram, Proyek Jembatan Mangkrak Bertahun-tahun'. Membaca kritis berarti...",options:["langsung ikut geram bersama warga lain & membagikan judulnya ke teman-teman sebelum membaca isi beritanya, kata-katanya terasa kuat & menyentuh","memisahkan bagian fakta (proyek belum selesai, sudah berapa tahun) dari bagian bermuatan ('geram', 'mangkrak') & mencari data di isi berita","percaya penuh pada judul karena wartawan biasanya meringkas seluruh isi berita dengan benar & lengkap tanpa menambahkan sudut pandangnya sendiri"],answer:1,explain:"Judul memadatkan & memberi emosi. Fakta pentingnya (berapa lama, mengapa berhenti, sumbernya) ada di isi berita, bukan di judul.",hint:"Cari fakta di isi, bukan di judul."},
{n:44,type:"open",micro:"Terapan: klaim teman",q:"Teman berkata: 'Semua guru di sekolah ini lebih menyukai murid perempuan.' Tuliskan mengapa ini klaim yang lemah & apa yang dibutuhkan untuk mengujinya secara adil.",explain:"Klaim menyeluruh tentang niat orang butuh bukti yang luas & terukur, bukan kesan.",hint:"Soroti kata 'semua' + usul cara mengukur.",sample:"Klaim ini lemah karena memakai kata 'semua' & menuduh perasaan yang tidak terlihat. Untuk mengujinya secara adil perlu bukti yang bisa diperiksa: misalnya membandingkan nilai, hukuman, atau kesempatan (ditunjuk menjawab, diberi tugas) antara murid laki-laki & perempuan dari beberapa guru selama waktu tertentu. Satu-dua pengalaman pribadi tidak cukup untuk klaim tentang 'semua guru'."},
{n:45,type:"mcq",micro:"Terapan: klaim sains",q:"Postingan: 'Tanaman tumbuh lebih cepat jika diajak bicara.' Sikap kritis:",options:["menganggapnya fakta ilmiah yang benar, sudah dibagikan banyak orang di media sosial & tak perlu diuji lagi oleh peneliti mana pun","menganggapnya hanya opini pemilik tanaman yang tak perlu diuji karena tanaman tak bisa mendengar & tak punya perasaan, jadi percobaan itu hanya membuang waktu","menganggapnya klaim yang bisa diuji: lakukan percobaan dengan dua kelompok tanaman yang diperlakukan sama kecuali 'diajak bicara', bandingkan pertumbuhannya"],answer:2,explain:"Klaim sebab-akibat bisa diuji dengan percobaan terkontrol. Berpikir kritis bukan menolak semua, tapi menuntut & merancang bukti.",hint:"Bagaimana cara menguji klaim ini?"},
{n:46,type:"order",micro:"Terapan: memeriksa angka viral",q:"Kamu melihat gambar berisi klaim '80% remaja tidak sarapan'. Urutkan langkah memeriksanya:",items:["Cari siapa yang pertama menerbitkan angka itu & kapan","Periksa bagaimana datanya dikumpulkan (siapa yang disurvei, berapa banyak, di mana)","Cari apakah lembaga tepercaya lain melaporkan angka serupa","Putuskan: percaya, ragukan, atau tolak berdasar temuan itu"],answer:[0,1,2,3],explain:"Telusuri sumber asli → periksa cara pengumpulan data → cek silang → simpulkan.",hint:"Cari sumber aslinya lebih dulu."},
{n:47,type:"mcq",micro:"Terapan: sejarah",q:"'Peristiwa itu terjadi pada tahun 1945' vs 'Peristiwa itu adalah momen paling membanggakan dalam sejarah'. Perbedaannya:",options:["yang pertama fakta bertanggal yang bisa dicek di sumber sejarah; yang kedua penilaian yang bisa berbeda antar orang","keduanya opini, sejarah ditulis oleh orang yang menyukai pelajaran itu & tidak bisa dicek lagi di sumber mana pun","keduanya fakta, karena sama-sama ditulis dalam buku sejarah dan diajarkan di sekolah kepada murid di semua kelas"],answer:0,explain:"Tanggal & urutan peristiwa adalah fakta sejarah yang bisa diperiksa. 'Paling membanggakan' adalah penilaian.",hint:"Tanggal vs penilaian."},
{n:48,type:"tf",micro:"Terapan: bintang ulasan",q:"Benar atau Salah: Satu ulasan yang ditulis sangat meyakinkan adalah data yang lebih kuat untuk menilai produk daripada rata-rata bintang dari 500 ulasan.",answer:false,explain:"Sebaliknya, banyak data mengurangi pengaruh pengalaman satu orang yang mungkin tidak khas — walau kita tetap perlu waspada pada ulasan palsu.",hint:"Banyak data > satu cerita meyakinkan."},
{n:49,type:"mcq",micro:"Terapan: pendapat vs laporan",q:"Di koran, kolom 'Opini' & halaman 'Berita' berbeda karena...",options:["keduanya sama saja, ditulis oleh wartawan yang sama & dicetak di koran yang sama setiap hari","halaman berita seharusnya melaporkan fakta yang diperiksa; kolom opini memang berisi pandangan penulis","kolom opini lebih benar karena ditulis penulis berpengalaman yang punya pendapat sendiri"],answer:1,explain:"Media yang baik memisahkan pelaporan fakta dari opini. Mengetahui kamu sedang membaca yang mana penting untuk menilainya.",hint:"Melaporkan vs berpendapat."},
{n:50,type:"mcq",micro:"Terapan: klaim kesehatan sekolah",q:"Poster UKS: 'Cuci tangan pakai sabun mengurangi risiko sakit perut & flu.' Ini...",options:["opini kesehatan seorang petugas UKS yang tak memerlukan bukti penelitian","prediksi tentang masa depan seseorang yang belum bisa diperiksa sekarang juga","klaim fakta yang didukung banyak penelitian kesehatan & lembaga resmi"],answer:2,explain:"Beberapa klaim kesehatan sudah didukung bukti kuat & konsensus lembaga. Menilai klaim berarti memeriksa kekuatan buktinya, bukan menolak semuanya.",hint:"Apakah bukti & lembaga resmi mendukungnya?"},
{n:51,type:"mcq",micro:"Terapan: kesaksian tunggal",q:"'Aku kenal orang yang merokok sampai tua & sehat, jadi merokok tidak berbahaya.' Kelemahannya:",options:["satu kasus tidak membatalkan bukti dari jutaan kasus & penelitian; itu memilih contoh yang cocok & mengabaikan gambaran besar","orang itu berbohong, orang yang merokok sampai tua tak mungkin sehat seperti yang ia ceritakan kepadamu dengan begitu yakin","tak ada kelemahan; pengalaman nyata seseorang yang kamu kenal sudah cukup menjadi bukti kuat bagi semua perokok"],answer:0,explain:"Contoh tunggal yang menyenangkan (anekdot) tidak mengalahkan kumpulan bukti besar. Ini disebut memilih ceri (cherry-picking).",hint:"Satu contoh vs jutaan data."},
{n:52,type:"open",micro:"Terapan: pisahkan di teks nyata",q:"Tulis satu paragraf pendek (3-4 kalimat) tentang tempat favoritmu yang memuat setidaknya dua fakta & dua opini, lalu tandai mana yang mana.",explain:"Berlatih menulis campuran fakta-opini sendiri membuat kita lebih cepat mengenalinya dalam tulisan orang lain.",hint:"2 fakta + 2 opini, beri label.",sample:"Pantai dekat rumah nenekku berjarak sekitar dua kilometer dari rumahnya (fakta). Air lautnya dangkal cukup jauh ke tengah (fakta). Menurutku itu pantai paling menenangkan yang pernah kukunjungi (opini). Warung di sana sebaiknya buka lebih pagi supaya pengunjung bisa sarapan (opini)."},
{n:53,type:"mcq",micro:"Terapan: grafik dalam iklan",q:"Iklan menampilkan grafik batang 'kepuasan pelanggan' tanpa menyebut berapa orang yang disurvei atau siapa yang membuat survei. Sikap kritis:",options:["percaya begitu saja; grafiknya terlihat meyakinkan & dibuat dengan warna menarik oleh pihak yang berpengalaman","grafik tanpa sumber & jumlah responden adalah klaim yang belum bisa diperiksa; perlakukan dengan hati-hati","abaikan iklan itu karena grafik dalam iklan hanya dibuat untuk menipu pembaca & merugikan pembeli"],answer:1,explain:"Tampilan visual membuat klaim terasa faktual. Bukti sebenarnya ada di detail: siapa, berapa, bagaimana diukur.",hint:"Grafik ≠ bukti bila sumbernya kosong."},
{n:54,type:"tf",micro:"Terapan: 'katanya'",q:"Benar atau Salah: Informasi yang disampaikan sebagai 'katanya' atau 'kata orang' sebaiknya diperlakukan sebagai klaim yang belum diperiksa, bukan fakta.",answer:true,explain:"'Katanya' tidak menyebut sumber yang bisa dicek. Sebelum menyebarkan, telusuri dari mana asalnya & apakah benar.",hint:"'Katanya' = sumber tidak jelas."},
{n:55,type:"mcq",micro:"Terapan: membandingkan dua klaim",q:"Klaim A: 'Menurut data dinas, 4 dari 10 jalan di kecamatan ini rusak.' Klaim B: 'Semua jalan di sini hancur total.' Mana yang lebih layak dipakai untuk berdiskusi?",options:["keduanya sama saja karena sama-sama berisi angka tentang jalan","Klaim B, karena kalimatnya lebih tegas & menggugah emosi","Klaim A, karena menyebut sumber & angka yang bisa diperiksa"],answer:2,explain:"Klaim yang menyebut sumber & angka spesifik bisa diuji & didiskusikan. Klaim yang melebih-lebihkan ('semua', 'hancur total') menghambat diskusi yang jernih.",hint:"Mana yang bisa dicek?"},
{n:56,type:"order",micro:"Terapan: menanggapi klaim di grup kelas",q:"Ada pesan di grup kelas: 'Besok libur mendadak, sudah pasti!' Urutkan tanggapan kritismu:",items:["Kenali ini klaim tentang masa depan yang perlu sumber resmi","Tanya: dari mana kabar ini? Ada pengumuman resmi dari sekolah?","Cek ke wali kelas atau kanal resmi sekolah","Baru teruskan atau luruskan berdasarkan hasil pengecekan"],answer:[0,1,2,3],explain:"Kenali jenis klaim → tanyakan sumber → verifikasi resmi → baru bertindak.",hint:"Jangan teruskan sebelum dicek."},
{n:57,type:"mcq",micro:"Terapan: opini yang berubah jadi fakta palsu",q:"Seseorang berkata berulang-ulang & dengan yakin 'Sekolah kita yang terbaik di kota' sampai banyak yang mengulanginya. Ini menunjukkan...",options:["pengulangan bisa membuat opini terasa seperti fakta, padahal statusnya tidak berubah tanpa bukti","pengulangan membuktikan klaim itu benar, banyak orang setuju & mengulanginya","pengulangan tak berpengaruh pada klaim karena opini hanya hidup di kepala satu orang saja"],answer:0,explain:"Pengulangan meningkatkan rasa familiar & keyakinan, tapi tidak menambah bukti. 'Terbaik' tetap perlu ukuran & data.",hint:"Sering diulang ≠ terbukti."},
{n:58,type:"mcq",micro:"Terapan: mana pertanyaan pengecek fakta",q:"Pertanyaan yang paling membantu memeriksa klaim '7 dari 10 murid di sini punya hewan peliharaan':",options:["'Siapa yang paling suka hewan peliharaan di sekolah ini?'","'Siapa yang menghitung, kapan, & berapa murid yang ditanya?'","'Apakah hewan peliharaan itu lucu, menggemaskan, & enak dipelihara?'"],answer:1,explain:"Memeriksa klaim angka berarti menanyakan cara data dikumpulkan & seberapa lengkap, bukan mengandalkan perasaan atau selera.",hint:"Tanyakan asal & cara pengumpulan data."},
{n:59,type:"tf",micro:"Terapan: fakta tidak nyaman",q:"Benar atau Salah: Sebuah fakta yang sudah didukung bukti kuat tetap benar meskipun kita tidak menyukainya.",answer:true,explain:"Rasa suka atau tidak suka tidak mengubah bukti. Berpikir kritis berarti menerima fakta yang terbukti walau tidak menyenangkan.",hint:"Perasaan tidak mengubah bukti."},
{n:60,type:"mcq",micro:"Ringkasan Penerapan",q:"Kebiasaan paling berguna saat membaca iklan, berita, & pesan berantai:",options:["percaya pada klaim yang disampaikan dengan yakin & banyak dibagikan, lalu menyebarkannya jika terdengar menarik","menolak setiap klaim di iklan & pesan berantai tanpa memeriksa lagi, semuanya dianggap bohong","bertanya 'ini fakta, opini, atau klaim?', lalu 'apa buktinya, dari mana, & cukupkah?' sebelum percaya atau menyebarkan"],answer:2,explain:"Menyortir jenis pernyataan & menuntut bukti melindungi kita dari iklan berlebihan, berita menyesatkan, & hoaks.",hint:"Jenis pernyataan → bukti → cukup?"},
{n:61,type:"mcq",micro:"Opini menyamar",q:"'Jelas sekali bahwa seragam baru itu jelek.' Kata 'jelas sekali' di sini...",options:["mencoba membuat opini terdengar seperti fakta yang tak terbantahkan","menegaskan bahwa pernyataan itu sudah dibuktikan lewat pengukuran","mengganti opini dengan angka tepat tentang seberapa jelek seragam itu"],answer:0,explain:"Frasa seperti 'jelas sekali', 'tentu saja', 'semua tahu' sering menyamarkan opini agar pembaca ragu untuk tidak setuju.",hint:"Kata yang menekan agar kamu setuju."},
{n:62,type:"mcq",micro:"Memilih ceri",q:"Seseorang mendukung klaim 'jajanan A paling laris' hanya dengan menyebut satu hari saat A terjual banyak, & mengabaikan enam hari lain saat A tidak laris. Ini disebut...",options:["pengumpulan bukti lengkap: menampilkan data dari tujuh hari secara berimbang","memilih ceri: hanya menampilkan bukti yang mendukung & menyembunyikan yang melawan","pengujian adil: membandingkan penjualan jajanan A dengan jajanan lain pada hari yang sama"],answer:1,explain:"Memilih ceri membuat klaim tampak kuat dengan menyembunyikan bukti yang tidak cocok. Selalu tanyakan: 'ada data lain yang tidak ditampilkan?'",hint:"Menampilkan yang cocok, menyembunyikan yang tidak."},
{n:63,type:"tf",micro:"Bukti melawan",q:"Benar atau Salah: Untuk menilai klaim dengan jujur, kita perlu mempertimbangkan bukti yang mendukung DAN bukti yang melawannya.",answer:true,explain:"Menimbang kedua sisi bukti adalah inti penilaian yang jujur. Hanya melihat satu sisi menghasilkan kesimpulan berat sebelah.",hint:"Timbang dua sisi bukti."},
{n:64,type:"mcq",micro:"Otoritas ≠ bukti otomatis",q:"Orang terkenal berkata 'Vitamin merek ini bikin anak jenius.' Sikap kritis:",options:["percaya begitu saja; orang terkenal tentu sudah mencoba produknya & tak mungkin berbohong tentang vitamin anak","menolak mentah-mentah karena orang terkenal itu dibayar, sehingga pendapat mereka tak pernah layak didengar","ketenaran bukan bukti; tanyakan apakah ada pengujian ilmiah & apakah orang itu ahli di bidangnya atau dibayar mengiklankan"],answer:2,explain:"Klaim dinilai dari buktinya, bukan dari siapa yang mengucapkannya. Tokoh terkenal bisa keliru atau punya kepentingan.",hint:"Terkenal ≠ ahli ≠ bukti."},
{n:65,type:"mcq",micro:"Fakta kabur",q:"Klaim 'Banyak murid mengeluh soal jadwal' menjadi lebih kuat bila diubah menjadi...",options:["'Dari 30 murid yang kutanya, 22 menyatakan keberatan dengan jadwal pulang sore'","'Murid kita sebenarnya sangat suka mengeluh tentang berbagai hal di sekolah.'","'Seluruh murid mengeluh soal jadwal ini & tak ada satu pun yang setuju dengannya.'"],answer:0,explain:"Angka & cara pengumpulan yang jelas mengubah klaim kabur menjadi klaim yang bisa diperiksa & dipercaya.",hint:"Ganti 'banyak' dengan angka & metode."},
{n:66,type:"open",micro:"Bongkar sebuah klaim",q:"Ambil klaim iklan mana pun yang kamu ingat (mis. 'sabun ini membunuh 99% kuman'). Tuliskan: bagian mana yang bisa diperiksa, pertanyaan apa yang akan kamu ajukan, & bukti apa yang akan meyakinkanmu.",explain:"Membongkar klaim berarti menemukan bagian yang bisa diuji, menanyakan metodenya, & menentukan bukti yang layak.",hint:"Bagian teruji + pertanyaan + bukti yang dicari.",sample:"Klaim: 'Sabun ini membunuh 99% kuman.' Bagian yang bisa diperiksa: angka 99% & kata 'kuman'. Pertanyaan: kuman jenis apa, diuji di laboratorium atau di tangan manusia, berapa lama kontak, dibandingkan dengan sabun biasa atau tanpa sabun? Bukti yang meyakinkan: hasil uji laboratorium independen yang menyebut metode & pembanding, bukan sekadar tulisan di kemasan."},
{n:67,type:"mcq",micro:"Fakta tanpa konteks",q:"'Tahun ini sekolah mengeluarkan 3 murid.' Angka ini bisa menyesatkan tanpa...",options:["warna sampul laporan & jenis huruf yang dipakai oleh petugas tata usaha di sekolah","konteks: dari berapa total murid, apa alasannya, & bagaimana dibanding tahun-tahun lain","nama kepala sekolah & tanggal laporan itu dicetak oleh bagian administrasi sekolah"],answer:1,explain:"Satu angka tanpa pembanding & alasan mudah ditafsirkan berlebihan. Konteks mengubah arti sebuah fakta.",hint:"3 dari berapa? Dibanding kapan?"},
{n:68,type:"mcq",micro:"Opini beralasan vs selera",q:"Beda 'opini beralasan' & 'selera pribadi':",options:["selera pribadi lebih kuat daripada opini beralasan karena tidak perlu dibela, sedangkan opini beralasan harus diperiksa & bisa ditolak orang lain, sehingga selera lebih layak dipakai dalam debat","keduanya sama saja karena sama-sama diucapkan seseorang tentang sesuatu yang ia lihat atau rasakan, jadi sama-sama tak perlu alasan atau bukti pendukung dari orang lain","opini beralasan didukung fakta & logika yang bisa didiskusikan (mis. 'buku ini membingungkan karena alurnya melompat'); selera pribadi tidak butuh alasan (mis. 'aku suka sampul warna hijau')"],answer:2,explain:"Keduanya sah, tetapi opini beralasan bisa diuji & diperdebatkan dengan bukti, sedangkan selera murni tidak perlu pembelaan.",hint:"Bisa didiskusikan dengan bukti vs tidak."},
{n:69,type:"tf",micro:"Semua opini setara?",q:"Benar atau Salah: Dalam soal yang bisa diuji bukti, opini seseorang yang sudah mempelajari datanya bertahun-tahun tetap setara dengan opini orang yang belum pernah melihat datanya.",answer:false,explain:"Untuk soal yang bergantung bukti, opini yang didasari pemahaman & data lebih berbobot. Kesetaraan berlaku pada selera, bukan pada penilaian berbasis fakta.",hint:"Berbasis data ≠ tebakan santai."},
{n:70,type:"order",micro:"Menilai klaim yang membelah pendapat",q:"Urutkan cara menilai klaim 'PR merugikan murid':",items:["Perjelas maksudnya: 'merugikan' dalam hal apa (nilai, tidur, minat belajar)?","Kumpulkan bukti dari berbagai penelitian, termasuk yang berlawanan","Timbang kekuatan & keterbatasan tiap bukti","Sampaikan kesimpulan sebagai penilaian beralasan, bukan kepastian mutlak"],answer:[0,1,2,3],explain:"Perjelas istilah → kumpulkan bukti dua arah → timbang → simpulkan dengan rendah hati.",hint:"Perjelas istilah dulu."},
{n:71,type:"tf",micro:"Fakta & opini bisa bercampur halus",q:"Benar atau Salah: Dalam tulisan yang tampak 'berisi fakta', bisa terselip opini lewat pilihan fakta mana yang ditonjolkan & mana yang dihilangkan.",answer:true,explain:"Menyeleksi fakta adalah bentuk opini yang halus. Bertanya 'fakta apa yang mungkin sengaja tidak disebut?' penting.",hint:"Memilih fakta = menyisipkan sudut pandang."},
{n:72,type:"mcq",micro:"Klaim tak terbantahkan",q:"Jika sebuah klaim dibuat sedemikian rupa sehingga tidak ada bukti apa pun yang bisa membantahnya (mis. 'ada naga tak terlihat & tak terdeteksi di ruangan ini'), maka klaim itu...",options:["lemah justru karena tak bisa diuji; klaim yang berguna harus bisa dibayangkan cara membuktikan salahnya","kuat justru karena tak bisa dibantah; klaim yang berguna harus kebal terhadap semua bukti yang ada","benar karena tak seorang pun mampu menunjukkan bukti yang melawannya, sehingga layak dipercaya"],answer:0,explain:"Klaim yang tak mungkin diuji tidak memberi kita cara untuk tahu. Klaim yang baik menyebutkan seperti apa bukti yang akan membantahnya.",hint:"Tak bisa diuji = tak berguna, bukan pasti benar."},
{n:73,type:"mcq",micro:"Angka menyesatkan",q:"'Penjualan naik 100%!' terdengar hebat, tapi bisa menyesatkan bila...",options:["angka awalnya sangat besar (mis. 2.000 menjadi 4.000)","angka awalnya sangat kecil (mis. dari 2 menjadi 4 unit)","kenaikannya dihitung dari penjualan yang dicatat resmi oleh toko"],answer:1,explain:"Persentase besar dari basis kecil bisa terlihat dramatis padahal jumlah nyatanya kecil. Selalu tanyakan angka mutlaknya.",hint:"100% dari berapa?"},
{n:74,type:"open",micro:"Saat kamu keliru menilai",q:"Ceritakan satu kali kamu menganggap sebuah opini sebagai fakta (atau sebaliknya), lalu menyadari kekeliruannya. Apa yang membuatmu sadar?",explain:"Menyadari kesalahan penilaian sendiri memperkuat kebiasaan memeriksa sebelum menyimpulkan.",hint:"Anggapan awal + apa yang mengubahnya.",sample:"Aku dulu menganggap 'game ini pasti membuat orang jadi malas belajar' sebagai fakta, karena sering mendengarnya. Setelah membaca beberapa artikel, aku sadar buktinya bercampur: sebagian orang tetap berprestasi, & yang penting adalah seberapa lama & kapan bermainnya. Yang membuatku sadar adalah menemukan bukti yang tidak cocok dengan anggapanku, lalu memeriksanya alih-alih mengabaikannya."},
{n:75,type:"mcq",micro:"Beban pembuktian",q:"Siapa yang seharusnya menyediakan bukti dalam sebuah klaim?",options:["orang yang mendengar klaim itu — dia harus membuktikan bahwa klaim salah","siapa saja yang kebetulan lewat & mau berdebat tentang klaim itu","orang yang membuat klaim itu — dialah yang menyatakan sesuatu benar"],answer:2,explain:"Yang mengajukan klaim menanggung tugas menunjukkan buktinya. Menuntut orang lain 'buktikan aku salah' bukan cara yang adil.",hint:"Yang mengklaim, yang membuktikan."},
{n:76,type:"tf",micro:"Konsensus bukti",q:"Benar atau Salah: Ketika hampir semua ahli yang mempelajari suatu bidang sepakat berdasarkan banyak bukti, kesepakatan itu lebih kuat daripada opini satu orang yang tidak menyertakan bukti.",answer:true,explain:"Konsensus ahli yang dibangun di atas banyak bukti independen adalah salah satu petunjuk terbaik yang kita punya — walau tetap terbuka untuk direvisi oleh bukti baru.",hint:"Banyak ahli + banyak bukti > satu suara tanpa bukti."},
{n:77,type:"mcq",micro:"Membingkai ulang",q:"'Setengah gelas kosong' vs 'setengah gelas penuh' menggambarkan fakta yang sama. Ini menunjukkan...",options:["cara sebuah fakta dibingkai (dipilih kata & sudutnya) bisa menggeser opini pembaca tanpa mengubah faktanya","fakta berubah bila diucapkan dengan kata yang berbeda, jadi fakta dalam berita tak bisa dipercaya sedikit pun","setengah gelas kosong lebih benar daripada setengah gelas penuh dan menunjukkan sisi nyata keadaannya"],answer:0,explain:"Pembingkaian memilih sisi mana yang ditonjolkan. Menyadarinya membantu kita melihat fakta apa adanya di balik pilihan kata.",hint:"Fakta sama, bingkai berbeda."},
{n:78,type:"mcq",micro:"Klaim + syarat",q:"Klaim yang paling jujur & mudah diuji biasanya...",options:["umum & tanpa syarat, seperti 'setiap', 'seluruh', atau 'mutlak', dan terdengar meyakinkan bagi pembaca","spesifik & menyebut syaratnya ('dalam kondisi X, biasanya terjadi Y pada sekitar Z kasus')","panjang & penuh istilah rumit, dan pembaca merasa klaim itu sudah dipikirkan matang"],answer:1,explain:"Klaim yang menyebut kondisi, ukuran, & kekecualian lebih mudah diperiksa & lebih jarang menyesatkan daripada klaim mutlak.",hint:"Spesifik & bersyarat > mutlak."},
{n:79,type:"mcq",micro:"Ingin percaya",q:"Kamu sangat ingin klaim 'kelasmu menang lomba kebersihan' itu benar. Bahaya dari keinginan ini saat menilai buktinya:",options:["keinginan itu otomatis membuat klaim jadi benar, jadi bukti tak perlu diperiksa","keinginan itu membantu, semangat memperkuat bukti yang dikumpulkan","kamu cenderung menerima bukti lemah yang mendukung & meragukan bukti yang melawan"],answer:2,explain:"Keinginan memihak (motivated reasoning) membengkokkan penilaian bukti. Sadari, lalu timbang bukti seolah hasilnya tidak menguntungkanmu.",hint:"Harapan melonggarkan standar bukti."},
{n:80,type:"mcq",micro:"Ringkasan Penalaran",q:"Tanda klaim yang perlu diwaspadai:",options:["memakai kata mutlak, kata bermuatan emosi, tanpa sumber, & hanya menampilkan bukti yang mendukung","ditulis dengan huruf besar & tanda seru, dibagikan banyak orang, dan terdengar sangat meyakinkan","menyebut sumber yang jelas, memberi angka, & menjelaskan kondisi di mana klaim itu berlaku serta batas ketidakpastiannya"],answer:0,explain:"Kata mutlak, muatan emosi, sumber kosong, & bukti sepihak adalah bendera merah. Kejujuran justru terdengar lebih berhati-hati.",hint:"Mutlak + emosi + tanpa sumber + sepihak."},
{n:81,type:"mcq",micro:"Bongkar paragraf",q:"'SMP Harapan adalah sekolah terbaik. Nilai rata-rata ujiannya 82, tertinggi di kecamatan tahun lalu. Semua orang tua pasti ingin anaknya di sini.' Kalimat mana yang klaim fakta yang bisa dicek?",options:["'SMP Harapan adalah sekolah yang terbaik di seluruh kota ini.'","'Nilai rata-rata ujiannya 82, tertinggi di kecamatan tahun lalu'","'Setiap orang tua ingin anaknya bersekolah di sana dengan bahagia.'"],answer:1,explain:"Angka rata-rata & peringkat kecamatan bisa diperiksa di data resmi. 'Terbaik' & 'semua orang tua pasti ingin' adalah opini/klaim menyeluruh tanpa bukti.",hint:"Cari kalimat berisi angka yang bisa dicek."},
{n:82,type:"open",micro:"Nilai sebuah klaim lengkap",q:"Klaim: 'Menghapus PR akan membuat nilai murid turun.' Tuliskan: (a) apakah ini fakta/opini/klaim & mengapa, (b) bukti apa yang akan mendukungnya, (c) bukti apa yang akan melawannya, (d) kesimpulan sementaramu.",explain:"Menilai klaim besar berarti mengenali jenisnya, membayangkan bukti dua arah, & berani menahan kesimpulan.",hint:"Jenis → bukti pro → bukti kontra → sikap sementara.",sample:"(a) Ini klaim sebab-akibat tentang masa depan, bukan fakta yang sudah pasti & bukan sekadar selera — jadi perlu bukti. (b) Mendukung: sekolah atau daerah yang menghapus PR lalu nilai ujiannya turun dibanding sebelumnya, dengan faktor lain yang sebanding. (c) Melawan: sekolah yang mengurangi PR tetapi nilainya stabil atau naik, atau penelitian yang menunjukkan PR berlebih tidak menaikkan nilai. (d) Kesimpulan sementara: hubungannya belum jelas & mungkin bergantung pada jenis & jumlah PR; aku belum bisa memastikan tanpa melihat data."},
{n:83,type:"mcq",micro:"Dua sumber bertentangan",q:"Dua sumber tepercaya memberi angka berbeda untuk hal yang sama. Langkah kritis:",options:["pilih angka yang lebih besar; data yang besar biasanya lebih lengkap & lebih meyakinkan bagi pembaca yang membandingkannya","anggap kedua sumber salah karena angka yang berbeda menunjukkan bahwa tidak ada sumber yang tepercaya di bidang itu","periksa kapan tiap data dikumpulkan, dengan metode apa, & untuk wilayah/kelompok mana — perbedaan sering berasal dari situ"],answer:2,explain:"Perbedaan angka biasanya bukan soal bohong, melainkan definisi, waktu, atau cakupan yang berbeda. Membaca metode menjelaskan selisihnya.",hint:"Beda metode, beda waktu, beda cakupan."},
{n:84,type:"tf",micro:"Fakta lama",q:"Benar atau Salah: Sebuah pernyataan fakta yang benar lima tahun lalu pasti masih akurat sekarang, jadi tidak perlu dicek ulang.",answer:false,explain:"Sebaliknya, data populasi, harga, & aturan berubah. Fakta yang baik menyertakan 'kapan' & perlu diperbarui.",hint:"Cek tanggal data."},
{n:85,type:"mcq",micro:"Opini dibungkus data",q:"'Berdasarkan survei kami, 100% pelanggan puas.' Bendera merah terbesar:",options:["angka 100% yang sangat mungkin berasal dari sampel kecil atau terpilih, & survei dibuat oleh pihak yang berkepentingan","kata 'pelanggan' yang terlalu umum & tidak menyebut nama toko, kota, ataupun tahun survei itu dilakukan","huruf iklan yang kecil & warna tulisan yang kurang kontras, hingga susah dibaca oleh pembeli"],answer:0,explain:"100% hampir tidak pernah realistis; & survei yang dibuat & dilaporkan oleh penjual sendiri rawan bias. Tanyakan jumlah responden & siapa yang mensurvei.",hint:"100% + survei sendiri = curigai."},
{n:86,type:"order",micro:"Alur menilai informasi apa pun",q:"Urutkan alur lengkap menilai sepotong informasi:",items:["Pisahkan tiap pernyataan: fakta yang bisa dicek, opini, atau klaim","Untuk klaim fakta, telusuri sumber asli & cara datanya dikumpulkan","Timbang bukti pendukung & bukti yang melawan, cek silang bila bisa","Perhatikan pembingkaian: kata bermuatan, fakta yang dihilangkan, angka tanpa konteks","Simpulkan tingkat keyakinanmu & bersedia memperbaruinya bila ada bukti baru"],answer:[0,1,2,3,4],explain:"Pisahkan jenis → telusuri sumber → timbang dua arah → periksa pembingkaian → simpulkan dengan keyakinan yang bisa direvisi.",hint:"Memisahkan jenis pernyataan lebih dulu."},
{n:87,type:"mcq",micro:"Fakta + inferensi + opini",q:"'Lampu di rumah Pak Rudi menyala sepanjang malam (fakta). Mungkin ada yang lupa mematikannya (inferensi). Boros sekali orang itu (opini).' Pelajaran dari contoh ini:",options:["tidak perlu membedakan fakta, dugaan, & penilaian karena semuanya sama-sama pernyataan tentang Pak Rudi","penting mengenali kapan kita berpindah dari fakta ke dugaan ke penilaian, karena tiap tingkat butuh sikap berbeda","fakta bisa disimpulkan langsung menjadi penilaian tentang sifat seseorang tanpa perlu bukti tambahan"],answer:1,explain:"Rantai fakta → inferensi → opini sering diucapkan dalam satu tarikan napas. Menyadari perpindahannya mencegah kita menilai orang berdasarkan dugaan.",hint:"Fakta, lalu dugaan, lalu penilaian — beda tingkat."},
{n:88,type:"open",micro:"Rancang uji klaim",q:"Klaim: 'Murid yang duduk di barisan depan mendapat nilai lebih tinggi.' Rancang cara sederhana & adil untuk memeriksa apakah klaim ini benar di kelasmu.",explain:"Menguji klaim berarti mengumpulkan data yang relevan, membandingkan secara adil, & mengakui kemungkinan penyebab lain.",hint:"Data apa, dibandingkan bagaimana, sebab lain apa.",sample:"Aku akan mencatat posisi duduk setiap murid selama beberapa minggu (karena tempat duduk kadang berganti) & nilai beberapa ulangan. Lalu aku bandingkan rata-rata nilai murid yang lebih sering duduk depan dengan yang lebih sering duduk belakang. Aku juga akan ingat bahwa mungkin ada sebab lain: murid yang memang rajin cenderung memilih duduk depan, jadi hasil ini belum tentu berarti 'duduk depan menyebabkan nilai naik'."},
{n:89,type:"mcq",micro:"Menahan penilaian",q:"Kapan sikap paling bijak adalah 'belum bisa kusimpulkan'?",options:["saat kamu tidak sependapat dengan klaim itu & ingin menghindari perdebatan dengan orang yang menyampaikan","saat klaim itu terdengar luar biasa tetapi sudah dibagikan oleh banyak orang yang kamu percayai","saat pernyataan bisa dicek tetapi bukti yang tersedia masih sedikit, bertentangan, atau sumbernya tidak jelas"],answer:2,explain:"Menahan penilaian saat bukti kurang bukanlah kelemahan, melainkan kejujuran intelektual.",hint:"Bukti kurang/bertentangan = tahan dulu."},
{n:90,type:"tf",micro:"Berpikir kritis ≠ sinis",q:"Benar atau Salah: Berpikir kritis terhadap klaim berarti menolak & mencurigai segalanya, termasuk fakta yang sudah didukung bukti kuat.",answer:false,explain:"Sebaliknya, berpikir kritis berarti menyesuaikan tingkat percaya dengan kekuatan bukti — percaya yang terdukung kuat, ragukan yang lemah, tolak yang bertentangan dengan bukti.",hint:"Menimbang bukti, bukan menolak semua."},
{n:91,type:"mcq",micro:"Kesaksian & rekaman",q:"Untuk klaim 'kemarin hujan deras pukul 3 sore di sekolah', bukti yang paling kuat:",options:["catatan cuaca resmi hari itu, foto/video bertanda waktu, & beberapa kesaksian yang cocok","cerita seorang teman yang yakin sekali & bersumpah bahwa hujan memang turun deras sore itu","perkiraan cuaca dari aplikasi untuk hari sebelumnya tanpa data pengamatan sesungguhnya"],answer:0,explain:"Bukti berlapis & bisa diperiksa (catatan resmi, rekaman bertanda waktu, kesaksian yang saling menguatkan) lebih kuat daripada satu ingatan.",hint:"Catatan + rekaman + kesaksian yang cocok."},
{n:92,type:"mcq",micro:"Opini yang layak dihormati",q:"Dalam diskusi kelas soal aturan yang bisa diperdebatkan (mis. panjang jam istirahat), opini yang paling layak dipertimbangkan:",options:["yang paling lantang & paling banyak didukung teman sekelas, walau tidak disertai alasan atau bukti","yang menyertakan alasan jelas & bukti (mis. data kelelahan, jadwal kegiatan) yang bisa ditanggapi orang lain","yang diucapkan oleh murid yang paling senior atau paling lama bersekolah di sekolah itu"],answer:1,explain:"Untuk soal yang bergantung nilai & bukti, kualitas alasan & bukti membuat opini layak dipertimbangkan, bukan volume suara atau pengulangan.",hint:"Alasan + bukti yang bisa ditanggapi."},
{n:93,type:"open",micro:"Panduan pribadi",q:"Tuliskan 3-4 pertanyaan yang akan kamu ajukan pada diri sendiri sebelum mempercayai atau membagikan sebuah informasi.",explain:"Daftar pertanyaan yang ringkas membuat pemeriksaan informasi menjadi kebiasaan, bukan usaha besar.",hint:"3-4 pertanyaan, dengan katamu sendiri.",sample:"1) Ini pernyataan fakta yang bisa dicek, opini, atau klaim yang belum terbukti? 2) Siapa sumber aslinya & apakah bisa dipercaya? 3) Apa bukti pendukungnya, & adakah bukti yang melawannya? 4) Apakah kata-katanya bermuatan emosi atau ada fakta penting yang sepertinya dihilangkan? Kalau aku tidak yakin, aku tahan dulu & cek sebelum membagikan."},
{n:94,type:"mcq",micro:"Revisi karena bukti",q:"Kamu yakin 'kantin tidak pernah menjual buah'. Lalu kamu melihat rak buah di kantin selama seminggu. Sikap yang tepat:",options:["berhenti pernah membicarakan kantin","tetap bilang kantin tidak jual buah, kamu sudah terlanjur berpendapat","perbarui pernyataanmu: kantin ternyata menjual buah, setidaknya minggu ini"],answer:2,explain:"Pernyataan fakta tunduk pada pengamatan. Bukti langsung yang jelas mengharuskan kita memperbarui klaim.",hint:"Lihat bukti → perbarui klaim."},
{n:95,type:"tf",micro:"Tujuan keterampilan ini",q:"Benar atau Salah: Tujuan membedakan fakta, opini, & klaim adalah agar kita bisa menyesuaikan seberapa yakin kita & menuntut bukti pada tempat yang tepat.",answer:true,explain:"Keterampilan ini bukan untuk memenangkan debat, melainkan untuk berpikir lebih akurat & tidak mudah tertipu atau menyesatkan orang lain.",hint:"Menyesuaikan keyakinan dengan bukti."},
{n:96,type:"mcq",micro:"Fakta dalam cerita persuasif",q:"Sebuah tulisan mengajakmu setuju dengan memakai banyak angka. Sebelum yakin, kamu tetap perlu memeriksa...",options:["apakah angka itu benar, dari sumber tepercaya, relevan dengan kesimpulan, & tidak dipilih sepihak","apakah angkanya banyak; makin banyak angka, biasanya buktinya makin kuat","apakah tulisannya panjang & rapi, karena tulisan yang rapi biasanya menandakan isinya benar"],answer:0,explain:"Banyaknya angka tidak menjamin kebenaran. Angka yang salah, tidak relevan, atau dipilih sepihak tetap menyesatkan.",hint:"Banyak angka ≠ benar."},
{n:97,type:"mcq",micro:"Kesimpulan terkuat",q:"Klaim: 'Perpustakaan sekolah kurang dimanfaatkan.' Bukti: catatan peminjaman menunjukkan rata-rata 4 buku/hari dari 600 murid, & survei 3 kelas menunjukkan sebagian besar tidak tahu jam bukanya. Kesimpulan paling didukung:",options:["perpustakaan sudah sangat dimanfaatkan; 4 buku per hari berarti lebih dari cukup bagi semua murid","pemanfaatan perpustakaan memang rendah, & salah satu sebabnya kemungkinan kurangnya informasi tentang jam buka","perpustakaan tidak bisa dinilai karena catatan peminjaman tidak ada hubungannya dengan pemanfaatannya"],answer:1,explain:"Data peminjaman + hasil survei sejalan mendukung 'pemanfaatan rendah + kemungkinan sebab: kurang informasi'. Menuduh 'malas' melampaui bukti; 'harus ditutup' adalah lompatan.",hint:"Kesimpulan yang pas dengan kedua bukti."},
{n:98,type:"order",micro:"Menanggapi pesan berantai",q:"Kamu menerima pesan berantai berisi klaim kesehatan yang menakutkan. Urutkan tindakanmu:",items:["Tahan dulu, jangan langsung meneruskan","Kenali: ini klaim fakta tentang kesehatan yang butuh sumber kuat","Cek ke sumber tepercaya (lembaga kesehatan resmi, tenaga medis)","Jika salah, jangan sebarkan; bila perlu luruskan dengan sopan ke pengirim"],answer:[0,1,2,3],explain:"Tahan → kenali jenis klaim → verifikasi ke sumber kuat → sebarkan hanya yang benar.",hint:"Menahan diri lebih dulu."},
{n:99,type:"open",micro:"Refleksi",q:"Menurutmu, mengapa orang kadang lebih mudah mempercayai klaim yang cocok dengan pendapat mereka daripada klaim yang melawannya? Bagaimana kamu bisa melawan kecenderungan ini pada dirimu sendiri?",explain:"Menyadari bias 'ingin percaya' pada diri sendiri adalah langkah pertama untuk menilai bukti lebih adil.",hint:"Kenapa nyaman? Cara mengeceknya sama kerasnya.",sample:"Klaim yang cocok terasa nyaman & tidak menuntut kita berubah pikiran, jadi kita jarang memeriksanya. Klaim yang melawan terasa mengganggu, jadi kita cari-cari alasan menolaknya. Untuk melawan ini, aku bisa sengaja bertanya 'bukti apa yang akan membuatku berubah pikiran?' & memeriksa klaim yang kusukai sekeras aku memeriksa yang tidak kusukai."},
{n:100,type:"mcq",micro:"Ringkasan Tantangan",q:"Inti keterampilan fakta-opini-klaim yang matang adalah...",options:["menerima pernyataan yang disampaikan dengan yakin, mengikuti opini mayoritas, dan membagikan yang menarik tanpa memeriksa sumbernya demi tidak ketinggalan informasi","menolak setiap klaim yang belum kamu buktikan sendiri, menganggap seluruh opini salah, & jarang mempercayai informasi dari orang lain, sehingga kamu bertindak sendirian","menyortir tiap pernyataan menurut jenisnya, menuntut bukti yang sepadan, memeriksa sumber & pembingkaian, & menyesuaikan keyakinan dengan kekuatan bukti"],answer:2,explain:"Berpikir jernih tentang informasi berarti tahu apa yang sedang dinilai, seberapa kuat buktinya, & seberapa yakin kita boleh — dengan pintu selalu terbuka untuk bukti baru.",hint:"Sortir jenis, tuntut bukti, cek sumber, sesuaikan keyakinan."},
];
